-- COMPLETE FOOD DELIVERY SAMPLE DATASET (MySQL)
-- Requires t.sql schema to be created first and all target tables to be empty.
-- Includes the 5,000-user base seed, 51 approved restaurants (3 per hub),
-- 20 customers with no orders, 10 drivers with no assigned orders, and 5 pending restaurants.
-- Expected total: 5,086 users and at least 4 approved restaurants in every hub.

-- Vietnamese synthetic food-delivery seed data; user names are sampled from data.csv.
-- Run t.sql first in an empty food_delivery_db database; then run this file.
-- 5,000 users: 4,633 customers, 200 restaurant owners, 150 drivers, 17 hub managers/admins.
-- Phone numbers, addresses, payment IDs, and bcrypt password hashes are synthetic demo data.
USE food_delivery_db;

START TRANSACTION;


























































































UPDATE `user`
SET `created_at` = DATE_ADD('2021-01-01 09:00:00', INTERVAL (`user_id` % 365) DAY);

WITH city_customers AS (
  SELECT c.`customer_id`, a.`city`, a.`district`, a.`address_line`,
    CASE WHEN a.`city` IN ('Hà Nội', 'Thành phố Hồ Chí Minh')
      THEN CONCAT(a.`city`, '|', a.`district`)
      ELSE a.`city` END AS `area_key`,
    ROW_NUMBER() OVER (
      PARTITION BY CASE WHEN a.`city` IN ('Hà Nội', 'Thành phố Hồ Chí Minh')
        THEN CONCAT(a.`city`, '|', a.`district`)
        ELSE a.`city` END
      ORDER BY c.`customer_id`
    ) - 1 AS `area_offset`,
    COUNT(*) OVER (
      PARTITION BY CASE WHEN a.`city` IN ('Hà Nội', 'Thành phố Hồ Chí Minh')
        THEN CONCAT(a.`city`, '|', a.`district`)
        ELSE a.`city` END
    ) AS `area_customer_count`
  FROM `customer` c JOIN `address` a ON a.`user_id` = c.`user_id`
)
UPDATE `order` o
JOIN `restaurant` r ON r.`restaurant_id` = o.`restaurant_id`
JOIN `hub` h ON h.`hub_id` = r.`hub_id`
JOIN city_customers cc ON cc.`area_key` = h.`operating_area`
  AND cc.`area_offset` = MOD(o.`order_id` - 1, cc.`area_customer_count`)
SET o.`customer_id` = cc.`customer_id`, o.`delivery_address_snapshot` = cc.`address_line`;


WITH hub_drivers AS (
  SELECT d.`driver_id`, d.`hub_id`,
    ROW_NUMBER() OVER (PARTITION BY d.`hub_id` ORDER BY d.`driver_id`) - 1 AS `driver_offset`,
    COUNT(*) OVER (PARTITION BY d.`hub_id`) AS `hub_driver_count`
  FROM `driver` d
)
UPDATE `order` o
JOIN `restaurant` r ON r.`restaurant_id` = o.`restaurant_id`
JOIN hub_drivers hd ON hd.`hub_id` = r.`hub_id`
  AND hd.`driver_offset` = MOD(o.`order_id` - 1, hd.`hub_driver_count`)
SET o.`driver_id` = hd.`driver_id`;

UPDATE `audit_log` al
JOIN `order` o ON o.`order_id` = al.`order_id`
JOIN `customer` c ON c.`customer_id` = o.`customer_id`
SET al.`changed_by` = c.`user_id`
WHERE al.`old_status` IS NULL;

UPDATE `audit_log` al
JOIN `order` o ON o.`order_id` = al.`order_id`
JOIN `restaurant` r ON r.`restaurant_id` = o.`restaurant_id`
LEFT JOIN `driver` d ON d.`driver_id` = o.`driver_id`
SET al.`changed_by` = CASE
  WHEN o.`status` IN ('PICKED_UP', 'DELIVERING', 'COMPLETED') THEN d.`user_id`
  ELSE r.`user_id`
END
WHERE al.`old_status` IS NOT NULL;

UPDATE `review` rv
JOIN `order` o ON o.`order_id` = rv.`order_id`
JOIN `customer` c ON c.`customer_id` = o.`customer_id`
SET rv.`reviewer_id` = c.`user_id`;

UPDATE `notification` n
JOIN `order` o ON n.`notification_id` = o.`order_id`
JOIN `customer` c ON c.`customer_id` = o.`customer_id`
SET n.`user_id` = c.`user_id`;

UPDATE `customer` c
LEFT JOIN (
  SELECT `customer_id`, COUNT(*) AS `order_count`
  FROM `order`
  GROUP BY `customer_id`
) totals ON totals.`customer_id` = c.`customer_id`
SET c.`total_orders` = COALESCE(totals.`order_count`, 0),
    c.`loyalty_points` = COALESCE(totals.`order_count`, 0) * 10;

UPDATE `shift` s
SET s.`completed_orders` = (
      SELECT COUNT(*)
      FROM `order` o
      WHERE o.`driver_id` = s.`driver_id`
        AND o.`status` = 'COMPLETED'
        AND o.`order_date` >= s.`start_time`
        AND o.`order_date` < s.`end_time`
    ),
    s.`bonus_earned` = (
      SELECT COUNT(*) * 10.0
      FROM `order` o
      WHERE o.`driver_id` = s.`driver_id`
        AND o.`status` = 'COMPLETED'
        AND o.`order_date` >= s.`start_time`
        AND o.`order_date` < s.`end_time`
    );

COMMIT;

-- MySQL incremental data: 51 restaurants (3 for each of the 17 existing hubs).
-- Adds restaurant-owner users, local addresses, restaurant records, and five menu items each.
-- Does not create tables or add transactional orders. Run after the original seed in food_delivery_db.
USE food_delivery_db;
SET NAMES utf8mb4;

SET @base_user_id := (SELECT COALESCE(MAX(user_id), 0) FROM `user`);
SET @batch_already_loaded := (SELECT COUNT(*) > 0 FROM restaurant WHERE business_license LIKE 'DEMO-ADD-%');

DROP TEMPORARY TABLE IF EXISTS tmp_added_restaurants;
CREATE TEMPORARY TABLE tmp_added_restaurants (seq INT NOT NULL PRIMARY KEY, hub_id INT NOT NULL, owner_name VARCHAR(100) NOT NULL, email_local VARCHAR(80) NOT NULL, password_hash VARCHAR(255) NOT NULL, restaurant_name VARCHAR(100) NOT NULL, cuisine_type VARCHAR(100) NOT NULL, ward VARCHAR(100) NOT NULL, district VARCHAR(100) NOT NULL, city VARCHAR(100) NOT NULL, street VARCHAR(150) NOT NULL);

