  SELECT 49 AS seq, 'Hub giao hàng Biên Hòa', 'Nguyễn Phương Duy', 'nguyenphuongduynhahang0005049', '$2b$10$EQy0IkVlYw3CAYp0O7OxOey3LY9y9KBwxiof8Ai0BQNmKsj38FmNW', 'Nguyễn Phương Duy', 'Cơm và món gia đình', 'Phường Tân Mai', 'Tam Hiệp', 'Biên Hòa', 'Đường Nguyễn Ái Quốc' UNION ALL
  SELECT 50 AS seq, 'Hub giao hàng Biên Hòa', 'Tăng Thúy Phụng', 'tangthuyphungnhahang0005050', '$2b$10$O2LeFG0ZYqxaY4oxRRNCmuiZCtwkWqNHR9HLH08T2.AGahUo6uBZW', 'Tăng Thúy Phụng', 'Phở và bún', 'Phường Long Bình Tân', 'Long Bình', 'Biên Hòa', 'Đường Cách Mạng Tháng Tám' UNION ALL
  SELECT 51 AS seq, 'Hub giao hàng Biên Hòa', 'Đặng Thị Dung', 'angthidungnhahang0005051', '$2b$10$UooDzgIEDH7J0o33AA3UaukGpQ2Sr3gsfaQg556C1DMUlfpFFs1vG', 'Đặng Thị Dung', 'Đặc sản địa phương', 'Phường Thanh Bình', 'Trấn Biên', 'Biên Hòa', 'Đường Nguyễn Ái Quốc'
) AS src
JOIN hub AS h ON h.name = src.hub_name;

SET @hub_rows_loaded := (SELECT COUNT(*) FROM tmp_added_restaurants);
SET @can_add_batch := (@hub_rows_loaded = 51 AND @batch_already_loaded = 0);
SELECT CASE WHEN @batch_already_loaded = 1 THEN 'Skipped: DEMO-ADD batch already present.' WHEN @hub_rows_loaded <> 51 THEN CONCAT('Skipped: expected 51 matching hubs, found ', @hub_rows_loaded, '.') ELSE 'Adding 51 restaurants and 255 menu items.' END AS batch_status;

START TRANSACTION;

SELECT @base_user_id + t.seq, t.owner_name, CONCAT('088', LPAD(@base_user_id + t.seq, 7, '0')), CONCAT(t.email_local, '@gmail.com'), t.password_hash, 'RESTAURANT',
       CONCAT(1 + MOD(t.seq * 7, 250), ' ', t.street, ', ', t.ward, ', ', t.district, ', ', t.city), DATE_ADD('2024-01-01 09:00:00', INTERVAL t.seq DAY)
FROM tmp_added_restaurants AS t WHERE @can_add_batch = 1 ORDER BY t.seq;

SELECT @base_user_id + t.seq, 'Restaurant', t.owner_name, CONCAT('088', LPAD(@base_user_id + t.seq, 7, '0')),
       CONCAT(1 + MOD(t.seq * 7, 250), ' ', t.street, ', ', t.ward, ', ', t.district, ', ', t.city), t.ward, t.district, t.city, NULL, NULL, 1
FROM tmp_added_restaurants AS t WHERE @can_add_batch = 1 ORDER BY t.seq;

SELECT @base_user_id + t.seq, CONCAT('DEMO-ADD-', LPAD(t.seq, 4, '0')), t.cuisine_type, '08:00-23:59', 18.00, t.hub_id, 1, 1, 50000.00
FROM tmp_added_restaurants AS t WHERE @can_add_batch = 1 ORDER BY t.seq;

DROP TEMPORARY TABLE IF EXISTS tmp_added_menu;
CREATE TEMPORARY TABLE tmp_added_menu (item_no INT NOT NULL PRIMARY KEY, item_name VARCHAR(100) NOT NULL, description TEXT NOT NULL, price DECIMAL(10,2) NOT NULL, category VARCHAR(50) NOT NULL);


SELECT r.restaurant_id, m.item_name, m.description, m.price, m.category, 1 FROM tmp_added_restaurants AS t
JOIN restaurant AS r ON r.user_id = @base_user_id + t.seq CROSS JOIN tmp_added_menu AS m
WHERE @can_add_batch = 1 ORDER BY t.seq, m.item_no;

COMMIT;

SELECT r.restaurant_id, u.name AS restaurant_owner, r.cuisine_type, h.name AS hub_name, COUNT(mi.menu_item_id) AS menu_item_count
FROM restaurant AS r JOIN `user` AS u ON u.user_id = r.user_id JOIN hub AS h ON h.hub_id = r.hub_id
LEFT JOIN menu_item AS mi ON mi.restaurant_id = r.restaurant_id WHERE r.business_license LIKE 'DEMO-ADD-%'
GROUP BY r.restaurant_id, u.name, r.cuisine_type, h.name ORDER BY h.hub_id, r.restaurant_id;

DROP TEMPORARY TABLE IF EXISTS tmp_added_menu;
DROP TEMPORARY TABLE IF EXISTS tmp_added_restaurants;

-- Add 20 customers with no orders, 10 drivers with no assigned orders,
-- and 5 restaurants awaiting approval.
-- Run once after the existing seed in the MySQL food_delivery_db database.
-- Adds user, address, customer, driver, and restaurant rows; it does not insert or update orders.
USE food_delivery_db;
SET NAMES utf8mb4;

SET @base_user_id := (SELECT COALESCE(MAX(user_id), 0) FROM `user`);
SET @batch_already_loaded := (SELECT COUNT(*) > 0 FROM `user` WHERE email LIKE 'lab2customer%@gmail.com' OR email LIKE 'lab2driver%@gmail.com');

DROP TEMPORARY TABLE IF EXISTS tmp_idle_profiles;
CREATE TEMPORARY TABLE tmp_idle_profiles (
  seq INT NOT NULL PRIMARY KEY, profile_type VARCHAR(10) NOT NULL, full_name VARCHAR(100) NOT NULL,
  password_hash VARCHAR(255) NOT NULL, hub_name VARCHAR(100) NOT NULL, ward VARCHAR(100) NOT NULL,
  district VARCHAR(100) NOT NULL, city VARCHAR(100) NOT NULL, street VARCHAR(150) NOT NULL,
  latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL,
  vehicle_type VARCHAR(50) NOT NULL, plate_number VARCHAR(20) NOT NULL
);


DROP TEMPORARY TABLE IF EXISTS tmp_unapproved_restaurants;
CREATE TEMPORARY TABLE tmp_unapproved_restaurants (
  seq INT NOT NULL PRIMARY KEY, owner_name VARCHAR(100) NOT NULL,
  email_local VARCHAR(80) NOT NULL, password_hash VARCHAR(255) NOT NULL,
  restaurant_name VARCHAR(100) NOT NULL, cuisine_type VARCHAR(100) NOT NULL,
  hub_name VARCHAR(100) NOT NULL, ward VARCHAR(100) NOT NULL,
  district VARCHAR(100) NOT NULL, city VARCHAR(100) NOT NULL,
  street VARCHAR(150) NOT NULL
);


SET @profile_rows := (SELECT COUNT(*) FROM tmp_idle_profiles);
SET @matched_hubs := (SELECT COUNT(*) FROM tmp_idle_profiles AS p JOIN hub AS h ON h.name = p.hub_name);
SET @phone_conflicts := (SELECT COUNT(*) FROM tmp_idle_profiles AS p JOIN `user` AS u ON u.phone = CONCAT('086', LPAD(@base_user_id + p.seq, 7, '0')));
SET @email_conflicts := (SELECT COUNT(*) FROM tmp_idle_profiles AS p JOIN `user` AS u ON u.email = CONCAT(CASE WHEN p.profile_type = 'CUSTOMER' THEN 'lab2customer' ELSE 'lab2driver' END, LPAD(p.seq, 4, '0'), '-', @base_user_id + p.seq, '@gmail.com'));
SET @can_add_batch := (@batch_already_loaded = 0 AND @profile_rows = 30 AND @matched_hubs = 30 AND @phone_conflicts = 0 AND @email_conflicts = 0);
SELECT CASE WHEN @batch_already_loaded = 1 THEN 'Skipped: this Lab 2 idle-user batch is already present.' WHEN @matched_hubs <> 30 THEN CONCAT('Skipped: expected 30 hub assignments, found ', @matched_hubs, '.') WHEN @phone_conflicts > 0 OR @email_conflicts > 0 THEN 'Skipped: a generated phone or email conflicts with an existing user.' WHEN @profile_rows <> 30 THEN CONCAT('Skipped: expected 30 profile rows, found ', @profile_rows, '.') ELSE 'Adding 20 customers with zero orders and 10 idle drivers.' END AS batch_status;
SET @pending_restaurant_batch_exists := (SELECT COUNT(*) > 0 FROM restaurant WHERE business_license LIKE 'DEMO-PENDING-%');
SET @pending_restaurant_rows := (SELECT COUNT(*) FROM tmp_unapproved_restaurants);
SET @pending_restaurant_hubs := (SELECT COUNT(*) FROM tmp_unapproved_restaurants AS t JOIN hub AS h ON h.name = t.hub_name);

START TRANSACTION;

SELECT @base_user_id + p.seq, p.full_name, CONCAT('086', LPAD(@base_user_id + p.seq, 7, '0')),
       CONCAT(CASE WHEN p.profile_type = 'CUSTOMER' THEN 'lab2customer' ELSE 'lab2driver' END, LPAD(p.seq, 4, '0'), '-', @base_user_id + p.seq, '@gmail.com'),
       p.password_hash, p.profile_type,
       CONCAT(1 + MOD(p.seq * 17, 250), ' ', p.street, ', ', p.ward, ', ', p.district, ', ', p.city), CURRENT_TIMESTAMP
FROM tmp_idle_profiles AS p JOIN hub AS h ON h.name = p.hub_name
WHERE @can_add_batch = 1 ORDER BY p.seq;

SELECT @base_user_id + p.seq, 'Home', p.full_name, CONCAT('086', LPAD(@base_user_id + p.seq, 7, '0')),
       CONCAT(1 + MOD(p.seq * 17, 250), ' ', p.street, ', ', p.ward, ', ', p.district, ', ', p.city),
       p.ward, p.district, p.city, p.latitude, p.longitude, 1
FROM tmp_idle_profiles AS p JOIN hub AS h ON h.name = p.hub_name
WHERE @can_add_batch = 1 ORDER BY p.seq;

SELECT @base_user_id + p.seq, 0, 0, 'CASH'
FROM tmp_idle_profiles AS p JOIN hub AS h ON h.name = p.hub_name
WHERE @can_add_batch = 1 AND p.profile_type = 'CUSTOMER' ORDER BY p.seq;

SELECT @base_user_id + p.seq, CONCAT('DEMO-IDLE-DL-', @base_user_id + p.seq), p.vehicle_type, p.plate_number, h.location, 'OFFLINE', h.hub_id
FROM tmp_idle_profiles AS p JOIN hub AS h ON h.name = p.hub_name
WHERE @can_add_batch = 1 AND p.profile_type = 'DRIVER' ORDER BY p.seq;

SET @pending_restaurant_base_user_id := (SELECT COALESCE(MAX(user_id), 0) FROM `user`);
SET @pending_restaurant_phone_conflicts := (
  SELECT COUNT(*) FROM tmp_unapproved_restaurants AS t
  JOIN `user` AS u ON u.phone = CONCAT('087', LPAD(@pending_restaurant_base_user_id + t.seq, 7, '0'))
);
SET @pending_restaurant_email_conflicts := (
  SELECT COUNT(*) FROM tmp_unapproved_restaurants AS t
  JOIN `user` AS u ON u.email = CONCAT(t.email_local, '-', @pending_restaurant_base_user_id + t.seq, '@gmail.com')
);
SET @can_add_pending_restaurants := (
  @pending_restaurant_batch_exists = 0 AND @pending_restaurant_rows = 5
  AND @pending_restaurant_hubs = 5 AND @pending_restaurant_phone_conflicts = 0
  AND @pending_restaurant_email_conflicts = 0
);
SELECT CASE
  WHEN @pending_restaurant_batch_exists = 1 THEN 'Skipped: the unapproved restaurant batch is already present.'
  WHEN @pending_restaurant_rows <> 5 THEN CONCAT('Skipped: expected 5 pending restaurants, found ', @pending_restaurant_rows, '.')
  WHEN @pending_restaurant_hubs <> 5 THEN CONCAT('Skipped: expected 5 matching hubs, found ', @pending_restaurant_hubs, '.')
  WHEN @pending_restaurant_phone_conflicts > 0 OR @pending_restaurant_email_conflicts > 0 THEN 'Skipped: a generated restaurant-owner phone or email conflicts with an existing user.'
  ELSE 'Adding 5 restaurants awaiting approval.'
END AS pending_restaurant_batch_status;

SELECT @pending_restaurant_base_user_id + t.seq, t.owner_name,
       CONCAT('087', LPAD(@pending_restaurant_base_user_id + t.seq, 7, '0')),
       CONCAT(t.email_local, '-', @pending_restaurant_base_user_id + t.seq, '@gmail.com'),
       t.password_hash, 'RESTAURANT',
       CONCAT(1 + MOD(t.seq * 11, 250), ' ', t.street, ', ', t.ward, ', ', t.district, ', ', t.city),
       CURRENT_TIMESTAMP
FROM tmp_unapproved_restaurants AS t
JOIN hub AS h ON h.name = t.hub_name
WHERE @can_add_pending_restaurants = 1
ORDER BY t.seq;

SELECT @pending_restaurant_base_user_id + t.seq, 'Restaurant', t.owner_name,
       CONCAT('087', LPAD(@pending_restaurant_base_user_id + t.seq, 7, '0')),
       CONCAT(1 + MOD(t.seq * 11, 250), ' ', t.street, ', ', t.ward, ', ', t.district, ', ', t.city),
       t.ward, t.district, t.city, NULL, NULL, 1
FROM tmp_unapproved_restaurants AS t
JOIN hub AS h ON h.name = t.hub_name
WHERE @can_add_pending_restaurants = 1
ORDER BY t.seq;

SELECT @pending_restaurant_base_user_id + t.seq, CONCAT('DEMO-PENDING-', LPAD(t.seq, 4, '0')),
       t.cuisine_type, '08:00-22:00', 18.00, h.hub_id, 0, 0, 50000.00
FROM tmp_unapproved_restaurants AS t
JOIN hub AS h ON h.name = t.hub_name
WHERE @can_add_pending_restaurants = 1
ORDER BY t.seq;

COMMIT;

-- Verify every new customer has zero orders.
SELECT u.user_id, u.name, c.customer_id, COUNT(o.order_id) AS order_count
FROM `user` AS u JOIN customer AS c ON c.user_id = u.user_id
LEFT JOIN `order` AS o ON o.customer_id = c.customer_id
WHERE u.email LIKE 'lab2customer%@gmail.com'
GROUP BY u.user_id, u.name, c.customer_id ORDER BY u.user_id;

-- Verify every new driver has zero assigned orders.
SELECT u.user_id, u.name, d.driver_id, d.hub_id, h.name AS hub_name, COUNT(o.order_id) AS assigned_order_count
FROM `user` AS u JOIN driver AS d ON d.user_id = u.user_id
JOIN hub AS h ON h.hub_id = d.hub_id
LEFT JOIN `order` AS o ON o.driver_id = d.driver_id
WHERE u.email LIKE 'lab2driver%@gmail.com'
GROUP BY u.user_id, u.name, d.driver_id, d.hub_id, h.name ORDER BY d.hub_id, u.user_id;

-- Verify the added restaurants are awaiting approval and are not open.
SELECT r.restaurant_id, u.name AS owner_name, r.cuisine_type, h.name AS hub_name,
       r.is_approved, r.is_open
FROM restaurant AS r
JOIN `user` AS u ON u.user_id = r.user_id
JOIN hub AS h ON h.hub_id = r.hub_id
WHERE r.business_license LIKE 'DEMO-PENDING-%'
ORDER BY r.restaurant_id;

DROP TEMPORARY TABLE IF EXISTS tmp_idle_profiles;
DROP TEMPORARY TABLE IF EXISTS tmp_unapproved_restaurants;

-- Final row counts for the complete data set.
SELECT 'user' AS table_name, COUNT(*) AS row_count FROM `user`
UNION ALL SELECT 'address', COUNT(*) FROM address
UNION ALL SELECT 'customer', COUNT(*) FROM customer
UNION ALL SELECT 'hub', COUNT(*) FROM hub
UNION ALL SELECT 'restaurant', COUNT(*) FROM restaurant
UNION ALL SELECT 'driver', COUNT(*) FROM driver
UNION ALL SELECT 'menu_item', COUNT(*) FROM menu_item
UNION ALL SELECT 'order', COUNT(*) FROM `order`
UNION ALL SELECT 'order_item', COUNT(*) FROM order_item
UNION ALL SELECT 'payment', COUNT(*) FROM payment
UNION ALL SELECT 'audit_log', COUNT(*) FROM audit_log
UNION ALL SELECT 'notification', COUNT(*) FROM notification
UNION ALL SELECT 'review', COUNT(*) FROM review
UNION ALL SELECT 'shift', COUNT(*) FROM shift;

-- Every hub should have at least four approved restaurants after the added batch.
SELECT h.hub_id, h.name,
       COUNT(DISTINCT CASE WHEN r.is_approved = 1 THEN r.restaurant_id END) AS approved_restaurant_count,
       COUNT(DISTINCT r.restaurant_id) AS total_restaurant_count
FROM hub AS h
LEFT JOIN restaurant AS r ON r.hub_id = h.hub_id
GROUP BY h.hub_id, h.name
ORDER BY h.hub_id;
